const mm = 1e-3, cm = 1e-2, cm2 = 1e-4, cm3 = 1e-6, cm4 = 1e-8, cm6 = 1e-12;

function buildUe(r) {
  const [des, massa, bw, bf, D, t, A, Ix, Wx, rx, Iy, Wy, ry, It, Cw, x0, xg, r0] = r;
  const tc = t / 10;                                             // cm
  const am = bw / 10 - tc, bm = bf / 10 - tc, cmm = D / 10 - tc / 2;
  const Jc = (am + 2 * bm + 2 * cmm) * tc ** 3 / 3;              // cm⁴
  return [des, {
    shape: 'Ue', designacao: des, massa,
    dims: { bw: bw * mm, bf: bf * mm, D: D * mm, t: t * mm, ri: t * mm },   // ri = t (NBR 6355:2012 Tab. A.3)
    A: A * cm2, Iz: Ix * cm4, Iy: Iy * cm4, Sz: Wx * cm3, Sy: Wy * cm3, rz: rx * cm, ry: ry * cm,
    J: Jc * cm4, JTab: It * cm4, Cw: Cw * cm6, x0: x0 * cm, xg: xg * cm, r0: r0 * cm,
    fonte: 'ABNT NBR 6355:2012 Tab. A.3',
  }];
}

function buildL(r) {
  const [des, massa, , b, , t, A, Ix, Wx, rx, Iy, Wy, ry, It, Cw, x0, xg, r0] = r;
  const tc = t / 10;
  const Jc = (2 * b / 10 - tc) * tc ** 3 / 3;
  const pr = LPRINC[des];
  return [des, {
    shape: 'L', designacao: des, massa,
    dims: { b: b * mm, t: t * mm, ri: t * mm },                     // ri = t (NBR 6355:2012 Tab. A.1)
    A: A * cm2, Iz: Ix * cm4, Iy: Iy * cm4, Sz: Wx * cm3, Sy: Wy * cm3, rz: rx * cm, ry: ry * cm,
    ...(pr ? { Izy: pr[0] * cm4, I1: pr[1] * cm4, I2: pr[2] * cm4, r2: pr[3] * cm } : {}),
    J: Jc * cm4, JTab: It * cm4, Cw: Cw * cm6, x0: x0 * cm, xg: xg * cm, r0: r0 * cm,
    fonte: 'ABNT NBR 6355:2012 Tab. A.1',
  }];
}

function buildZ(lip) {
  return (r) => {
    const [des, massa, bw, bf, D, t, A, Ix, Wx, rx, Iy, Wy, ry, Ixy, I1, I2, ap, It, Cw, r0, pg] = r;
    return [des, {
      shape: 'Z', lip, designacao: des, massa,
      dims: { bw: bw * mm, bf: bf * mm, D: D * mm, t: t * mm, ri: t * mm },
      A: A * cm2, Iz: Ix * cm4, Iy: Iy * cm4, Sz: Wx * cm3, Sy: Wy * cm3, rz: rx * cm, ry: ry * cm,
      Izy: Ixy * cm4, I1: I1 * cm4, I2: I2 * cm4, alphaP: ap,           // principal axes (αp from x, degrees)
      J: It * cm4, JTab: It * cm4, Cw: Cw * cm6, x0: 0, xg: 0,
      r0: Math.sqrt(rx * rx + ry * ry) * cm, r0Tab: r0 * cm,             // errata: shear centre = centroid
      fonte: `ABNT NBR 6355:2012 Tab. ${lip === 90 ? 'A.4' : 'A.5'} (doc p.${pg})`,
    }];
  };
}

function buildCr(r) {
  const [des, massa, bw, bf, D, t, A, Ix, Wx, rx, Iy, Wy, ry, yg, y0, It, Cw, r0, pg] = r;
  return [des, {
    shape: 'Cr', designacao: des, massa,
    dims: { bw: bw * mm, bf: bf * mm, D: D * mm, t: t * mm, ri: t * mm },
    A: A * cm2, Iz: Ix * cm4, Iy: Iy * cm4, Sz: Wx * cm3, Sy: Wy * cm3, rz: rx * cm, ry: ry * cm,
    J: It * cm4, JTab: It * cm4, Cw: Cw * cm6, yg: yg * cm, y0Tab: y0 * cm, r0Tab: r0 * cm,   // y0/r0 as printed — suspect, see note
    fonte: `ABNT NBR 6355:2012 Tab. A.6 (doc p.${pg})`,
  }];
}

