function buildU(r) {
  const [des, massa, bw, bf, t, ri, A, Ix, Wx, rx, Iy, Wy, ry, xg, x0, It, Cw, r0] = r;
  const tc = t / 10;                                             // cm
  const am = bw / 10 - tc, bm = bf / 10 - tc / 2;
  const Jc = (am + 2 * bm) * tc ** 3 / 3;                       // cm⁴, mid-line (same rule as the Ue entries)
  return [des, {
    shape: 'U', designacao: des, massa: massa ?? +(0.785 * A).toFixed(2),
    dims: { bw: bw * mm, bf: bf * mm, D: 0, t: t * mm, ri: ri * mm },
    A: A * cm2, Iz: Ix * cm4, Iy: Iy * cm4, Sz: Wx * cm3, Sy: Wy * cm3, rz: rx * cm, ry: ry * cm,
    J: Jc * cm4, JTab: It * cm4, Cw: Cw * cm6, x0: x0 * cm, xg: xg * cm, r0: r0 * cm,
    fonte: 'ABNT NBR 6355:2012 Tab. A.2',
  }];
}

export const CF_PROFILES = Object.fromEntries([...UE.map(buildUe), ...LCANT.map(buildL), ...U_SIMPLES.map(buildU),
  ...Z90.map(buildZ(90)), ...Z45.map(buildZ(45)), ...CR.map(buildCr)]);

/** Names of the catalogue (optionally only one shape: 'Ue' | 'U' | 'L' | 'Z' | 'Cr'). */
export function cfNames(shape) {
  return Object.keys(CF_PROFILES).filter(n => !shape || CF_PROFILES[n].shape === shape);
}

/** Profile (SI) or null. */
export function cfProfile(name) { return CF_PROFILES[name] || null; }

/** `sec` object ready for nbr14762.check (SI; same object as the catalogue entry, copied). */
export function cfSection(name) {
  const p = CF_PROFILES[name];
  return p ? { ...p, dims: { ...p.dims } } : null;
}
